import * as fs from "node:fs";
import * as path from "node:path";

export interface SecurityPolicy {
  version?: string;
  blockedCommands?: string[];
  protectedPaths?: string[];
  allowedDomains?: string[];
  allowExternalSymlinks?: boolean;
}

const DEFAULT_BLOCKED_COMMANDS = [
  "rm -rf /",
  "rm -rf /*",
  "mkfs",
  "dd if=",
  ":(){ :|:& };:",
  "> /dev/sd",
  "shutdown",
  "reboot",
  "chmod -R 777 /",
  "chown -R root /",
];

const DEFAULT_PROTECTED_PATHS = [
  ".git",
  // The operator's list of trusted workspaces: the agent must not trust a workspace for itself.
  "trusted_workspaces.json",
  ".env*",
  "id_rsa*",
  "id_ed25519*",
];

export function splitShellWords(cmd: string): string[] {
  const words: string[] = [];
  let current = "";
  let inSingleQuote = false;
  let inDoubleQuote = false;
  let escaped = false;

  for (let i = 0; i < cmd.length; i++) {
    const ch = cmd[i];
    if (escaped) {
      current += ch;
      escaped = false;
      continue;
    }
    if (ch === "\\") {
      escaped = true;
      continue;
    }
    if (ch === "'" && !inDoubleQuote) {
      inSingleQuote = !inSingleQuote;
      continue;
    }
    if (ch === '"' && !inSingleQuote) {
      inDoubleQuote = !inDoubleQuote;
      continue;
    }
    if (!inSingleQuote && !inDoubleQuote && /\s/.test(ch)) {
      if (current.length > 0) {
        words.push(current);
        current = "";
      }
      continue;
    }
    current += ch;
  }
  if (current.length > 0) {
    words.push(current);
  }
  return words;
}

export function splitSubcommands(cmd: string): string[][] {
  const tokens = splitShellWords(cmd);
  const subcommands: string[][] = [];
  let current: string[] = [];

  for (const token of tokens) {
    if (token === ";" || token === "&&" || token === "||" || token === "|" || token === "&") {
      if (current.length > 0) {
        subcommands.push(current);
        current = [];
      }
    } else if (token.includes(";") || token.includes("&") || token.includes("|")) {
      let buf = "";
      for (const ch of token) {
        if (ch === ";" || ch === "&" || ch === "|") {
          if (buf.length > 0) {
            current.push(buf);
            buf = "";
          }
          if (current.length > 0) {
            subcommands.push(current);
            current = [];
          }
        } else {
          buf += ch;
        }
      }
      if (buf.length > 0) {
        current.push(buf);
      }
    } else {
      current.push(token);
    }
  }
  if (current.length > 0) {
    subcommands.push(current);
  }
  return subcommands;
}

export class SecurityManager {
  private policy: SecurityPolicy;
  private workspace: string;

  constructor(workspace: string) {
    this.workspace = path.resolve(workspace);
    this.policy = this.loadPolicy();
  }

  public reload(): void {
    this.policy = this.loadPolicy();
  }

  private loadPolicy(): SecurityPolicy {
    const policyPath = path.join(this.workspace, ".nexus-security.json");
    if (fs.existsSync(policyPath)) {
      try {
        const raw = fs.readFileSync(policyPath, "utf-8");
        const parsed = JSON.parse(raw);
        return {
          blockedCommands: [
            ...DEFAULT_BLOCKED_COMMANDS,
            ...(Array.isArray(parsed.blockedCommands) ? parsed.blockedCommands : []),
          ],
          protectedPaths: [
            ...DEFAULT_PROTECTED_PATHS,
        }
      }
    }

    return { blocked: false };
  }

