          output: JSON.stringify({
            dry_run: true,
            path: args.path,
            action: "patch_file",
            message: `[DRY-RUN SIMULATION] Would patch ${args.path}. No changes written to disk.`,
          }),
        };
      }
      if (toolName === "delete_file") {
        return {
          success: true,

